export default function ProfileScreen() {
  const router = useRouter();
  const { userInfo, userToken, logout, refreshUserInfo, handle401Error } = useAuth();
  const [topupLoading, setTopupLoading] = useState(false);
  const [adminPanelVisible, setAdminPanelVisible] = useState(false);
  const [changePwdVisible, setChangePwdVisible] = useState(false);
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [changePwdLoading, setChangePwdLoading] = useState(false);
  const [deleteAccVisible, setDeleteAccVisible] = useState(false);
  const [deleteAccPassword, setDeleteAccPassword] = useState('');
  const [deleteAccLoading, setDeleteAccLoading] = useState(false);

  const handleTopup = async (amount: number = 50) => {
    if (!userToken) return;
    setTopupLoading(true);
    try {
      const data = await userApi.topup(userToken, amount, handle401Error);
      Alert.alert('Top Up Success', `+${data.credits_added} credits\nTotal: ${data.credits_total} credits`);
      await refreshUserInfo();
    } catch (err: unknown) {
      Alert.alert('Top Up Failed', err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setTopupLoading(false);
    }
  };

  const handleChangePassword = async () => {
    if (!newPassword || newPassword.length < 6) {
      Alert.alert('Error', 'New password must be at least 6 characters');
      return;
    }
    if (newPassword !== confirmPassword) {
      Alert.alert('Error', 'New password and confirmation do not match');
      return;
    }
    if (!userToken) return;
    setChangePwdLoading(true);
    try {
      await authApi.changePassword(userToken, oldPassword, newPassword, handle401Error);
      Alert.alert('Success', 'Password updated. Please login again.');
      setChangePwdVisible(false);
      setOldPassword('');
      setNewPassword('');
      setConfirmPassword('');
      await logout();
      router.replace('/auth/login');
    } catch (err: unknown) {
      Alert.alert('Change Password Failed', err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setChangePwdLoading(false);
    }
  };

  const handleLogout = async () => {
    if (Platform.OS === 'web' && typeof window !== 'undefined') {
      // Web 端使用 window.confirm 替代 Alert.alert（兼容性更好）
      const confirmed = window.confirm('Are you sure you want to logout?');
      if (confirmed) {
        await logout();
        router.replace('/auth/login');
      }
    } else {
      Alert.alert('Logout', 'Are you sure you want to logout?', [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Logout',
          style: 'destructive',
          onPress: async () => {
            await logout();
            router.replace('/auth/login');
          },
        },
      ]);
    }
  };
